SELECT COUNT(*)
FROM cmt
WHERE pst_id = #{pstId}

SELECT cmt_id AS cmtId, cmt_parent AS cmtParent, cmt_text AS cmtText, cmt_create_date AS cmtCreateDate, pst_id AS pstId, like_cnt AS likeCount 
FROM cmt
WHERE pst_id = #{pstId}
ORDER BY cmt_create_date DESC
LIMIT #{offset}, #{limit}

SELECT cmt_id AS cmtId, cmt_parent AS cmtParent, cmt_text AS cmtText, cmt_create_date AS cmtCreateDate, pst_id AS pstId, like_cnt AS likeCount  
FROM cmt
WHERE pst_id = #{pstId}
ORDER BY cmt_create_date DESC
LIMIT #{offset}, #{limit}

SELECT cmt_id AS cmtId, cmt_parent AS cmtParent, cmt_text AS cmtText, cmt_create_date AS cmtCreateDate, pst_id AS pstId, like_cnt AS likeCount  
FROM cmt
WHERE pst_id = #{pstId}
ORDER BY cmt_create_date ASC
LIMIT #{offset}, #{limit}

SELECT cmt_id AS cmtId, cmt_parent AS cmtParent, cmt_text AS cmtText, cmt_create_date AS cmtCreateDate, pst_id AS pstId, like_cnt AS likeCount 
FROM cmt
WHERE cmt_id = #{cmtId}

mapper.update:
UPDATE cmt
SET like_cnt = (
    SELECT COUNT(*)
    FROM `like`
    WHERE cmt_id = #{cmtId}
)
WHERE cmt_id = #{cmtId}
